<?php require 'config/bootstrap.php'; require_login(); $id=(int)($_GET['id']??0); $c=own_contract($id); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check(); $do=$_POST['do']??'';
 if($do==='archive'){ $pdo->prepare("UPDATE contracts SET status='archived' WHERE id=? AND user_id=?")->execute([$id,uid()]); log_act('contract_archived',$id); flash('Archived.'); }
 elseif($do==='status'&&in_array($_POST['status']??'',['draft','under_review','active','expired'],true)){ $pdo->prepare('UPDATE contracts SET status=? WHERE id=? AND user_id=?')->execute([$_POST['status'],$id,uid()]); log_act('status_changed',$id,$_POST['status']); flash('Status updated.'); }
 elseif($do==='obligation'&&trim($_POST['description']??'')!==''){ $dd=valid_date($_POST['due_date']??''); $pdo->prepare('INSERT INTO obligations(contract_id,description,responsible_party,due_date,priority) VALUES(?,?,?,?,?)')->execute([$id,trim($_POST['description']),trim($_POST['party']??''),$dd,in_array($_POST['priority']??'',['low','medium','high'])?$_POST['priority']:'medium']); log_act('obligation_added',$id,$_POST['description']); flash('Obligation added.'); }
 elseif($do==='ob_status'&&in_array($_POST['status']??'',['pending','in_progress','completed','cancelled'],true)){ $pdo->prepare('UPDATE obligations SET status=? WHERE id=? AND contract_id=?')->execute([$_POST['status'],(int)$_POST['oid'],$id]); log_act('obligation_'.$_POST['status'],$id); flash('Obligation updated.'); }
 elseif($do==='payment'&&is_numeric($_POST['amount']??'')&&$_POST['amount']>=0&&($pd=valid_date($_POST['due_date']??''))){ $pdo->prepare('INSERT INTO payments(contract_id,expected_amount,currency,due_date,notes) VALUES(?,?,?,?,?)')->execute([$id,number_format((float)$_POST['amount'],2,'.',''),strtoupper(substr($_POST['currency']??'INR',0,3)),$pd,trim($_POST['notes']??'')]); log_act('payment_added',$id); flash('Payment scheduled.'); }
 elseif($do==='pay'&&is_numeric($_POST['paid']??'')&&($pdt=valid_date($_POST['paid_date']??''))){ $s=$pdo->prepare('SELECT expected_amount FROM payments WHERE id=? AND contract_id=?');$s->execute([(int)$_POST['pid'],$id]);$ex=$s->fetchColumn();
   if($ex!==false){ $paid=number_format((float)$_POST['paid'],2,'.',''); $stt=bccomp($paid,$ex,2)>=0?'paid':'partial'; $pdo->prepare('UPDATE payments SET paid_amount=?,paid_date=?,status=? WHERE id=? AND contract_id=?')->execute([$paid,$pdt,$stt,(int)$_POST['pid'],$id]); log_act('payment_recorded',$id,$paid); flash('Payment recorded.'); } }
 elseif($do==='note'&&trim($_POST['body']??'')!==''){ $pdo->prepare('INSERT INTO review_notes(contract_id,user_id,body) VALUES(?,?,?)')->execute([$id,uid(),trim($_POST['body'])]); log_act('note_added',$id); flash('Note added.'); }
 elseif($do==='manual_text'&&trim($_POST['text']??'')!==''){ $vid=(int)$_POST['vid']; $t=trim($_POST['text']); $pdo->prepare("UPDATE contract_versions SET extracted_text=?,extraction_method='manual',extraction_status='manual',extraction_error=NULL,word_count=? WHERE id=? AND contract_id=?")->execute([$t,str_word_count($t),$vid,$id]); log_act('manual_text',$id); flash('Text saved.'); }
 header("Location: contract.php?id=$id"); exit; }
$v=$pdo->prepare('SELECT * FROM contract_versions WHERE contract_id=? ORDER BY id DESC');$v->execute([$id]);$vers=$v->fetchAll();
$o=$pdo->prepare('SELECT * FROM obligations WHERE contract_id=? ORDER BY due_date IS NULL,due_date');$o->execute([$id]);$obs=$o->fetchAll();
$p=$pdo->prepare('SELECT * FROM payments WHERE contract_id=? ORDER BY due_date');$p->execute([$id]);$pays=$p->fetchAll();
$n=$pdo->prepare('SELECT n.*,u.name FROM review_notes n JOIN users u ON u.id=n.user_id WHERE contract_id=? ORDER BY n.id DESC');$n->execute([$id]);$notes=$n->fetchAll();
$h=$pdo->prepare('SELECT * FROM activity_logs WHERE contract_id=? ORDER BY id DESC LIMIT 15');$h->execute([$id]);$hist=$h->fetchAll();
$today=date('Y-m-d'); page_head($c['title']); ?>
<div class="d-flex justify-content-between align-items-start mb-3"><div><h1 class="h3 mb-0"><?=e($c['title'])?></h1><span class="text-muted"><?=e($c['contract_type'])?> · <?=e($c['parties'])?> · <?=e($c['effective_date']?:'?')?> to <?=e($c['expiry_date']?:'?')?></span></div>
<form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="do" value="status"><select name="status" class="form-select form-select-sm"><?php foreach(['draft','under_review','active','expired'] as $x):?><option <?=$c['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-light">Set</button></form></div>
<div class="alert alert-secondary d-flex gap-3 flex-wrap align-items-center"><span>Risk level (heuristic): <strong><?=e($c['risk_level'])?></strong></span><a class="btn btn-sm btn-primary" href="analysis.php?id=<?=$id?>">Analysis and obligation review</a><a class="btn btn-sm btn-outline-light" href="compare.php?id=<?=$id?>">Versions and comparison</a><a class="btn btn-sm btn-outline-light" href="contract_edit.php?id=<?=$id?>">Edit / delete</a><a class="btn btn-sm btn-outline-light" href="report.php?id=<?=$id?>" target="_blank">Report (PDF)</a><span class="text-muted">LLM summary and Copilot: not available in this build.</span></div>
<div class="cardx mb-3"><h2 class="h6">Document</h2><?php if(!$vers):?><div class="empty">No document uploaded.</div><?php endif; foreach($vers as $x):?>
<p><?=e($x['version_label'])?> · <?=e($x['original_name'])?> · <strong><?=e($x['extraction_status'])?></strong> via <?=e($x['extraction_method'])?> · <?=e($x['word_count'])?> words · <a href="download.php?id=<?=$x['id']?>">Download</a></p>
<?php if($x['extraction_error']):?><div class="alert alert-warning"><?=e($x['extraction_error'])?></div><?php endif; if($x['extracted_text']!==''):?><pre class="doc"><?=e($x['extracted_text'])?></pre><?php else:?>
<form method="post"><?=csrf_field()?><input type="hidden" name="do" value="manual_text"><input type="hidden" name="vid" value="<?=$x['id']?>"><textarea class="form-control mb-2" name="text" rows="4" placeholder="Paste contract text manually"></textarea><button class="btn btn-sm btn-primary">Save text</button></form><?php endif; endforeach;?></div>
<div class="cardx mb-3"><h2 class="h6">Obligations</h2><?php if(!$obs):?><div class="empty">None yet.</div><?php else:?><div class="table-responsive"><table class="table"><tr><th>Description</th><th>Party</th><th>Due</th><th>Status</th><th></th></tr><?php foreach($obs as $x):$od=$x['due_date']&&$x['due_date']<$today&&in_array($x['status'],['pending','in_progress']);?><tr><td><?=e($x['description'])?></td><td><?=e($x['responsible_party'])?></td><td><?=e($x['due_date']?:'—')?><?=$od?' <span class="badge bg-danger">overdue</span>':''?></td><td><?=e($x['status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="do" value="ob_status"><input type="hidden" name="oid" value="<?=$x['id']?>"><select name="status" class="form-select form-select-sm"><?php foreach(['pending','in_progress','completed','cancelled'] as $s):?><option <?=$x['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-light">Save</button></form></td></tr><?php endforeach;?></table></div><?php endif;?>
<form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="do" value="obligation"><div class="col-md-5"><input class="form-control" name="description" placeholder="Obligation" required></div><div class="col-md-2"><input class="form-control" name="party" placeholder="Responsible"></div><div class="col-md-2"><input class="form-control" type="date" name="due_date"></div><div class="col-md-2"><select class="form-select" name="priority"><option>medium</option><option>high</option><option>low</option></select></div><div class="col-auto"><button class="btn btn-primary">Add</button></div></form></div>
<div class="cardx mb-3"><h2 class="h6">Payments (tracker only, not a gateway)</h2><?php if(!$pays):?><div class="empty">None scheduled.</div><?php else:?><div class="table-responsive"><table class="table"><tr><th>Due</th><th>Expected</th><th>Paid</th><th>Outstanding</th><th>Status</th><th></th></tr><?php foreach($pays as $x):?><tr><td><?=e($x['due_date'])?></td><td><?=e($x['currency'].' '.$x['expected_amount'])?></td><td><?=e($x['paid_amount']??'—')?></td><td><?=e(bcsub($x['expected_amount'],$x['paid_amount']??'0',2))?></td><td><?=e($x['status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="do" value="pay"><input type="hidden" name="pid" value="<?=$x['id']?>"><input class="form-control form-control-sm" name="paid" placeholder="Amount paid" required><input class="form-control form-control-sm" type="date" name="paid_date" value="<?=$today?>" required><button class="btn btn-sm btn-outline-light">Record</button></form></td></tr><?php endforeach;?></table></div><?php endif;?>
<form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="do" value="payment"><div class="col-md-3"><input class="form-control" name="amount" placeholder="Expected amount" required></div><div class="col-md-2"><input class="form-control" name="currency" value="INR" maxlength="3"></div><div class="col-md-3"><input class="form-control" type="date" name="due_date" required></div><div class="col-md-3"><input class="form-control" name="notes" placeholder="Notes"></div><div class="col-auto"><button class="btn btn-primary">Schedule</button></div></form></div>
<div class="row g-3"><div class="col-md-6"><div class="cardx"><h2 class="h6">Notes</h2><form method="post" class="mb-2"><?=csrf_field()?><input type="hidden" name="do" value="note"><textarea class="form-control mb-2" name="body" rows="2" required></textarea><button class="btn btn-sm btn-primary">Add note</button></form><?php foreach($notes as $x):?><p class="mb-1"><?=nl2br(e($x['body']))?> <span class="text-muted">· <?=e($x['name'])?> · <?=e($x['created_at'])?></span></p><?php endforeach;?></div></div>
<div class="col-md-6"><div class="cardx"><h2 class="h6">Activity</h2><?php foreach($hist as $x):?><p class="mb-1"><?=e($x['action'])?> <span class="text-muted"><?=e($x['detail'])?> · <?=e($x['created_at'])?></span></p><?php endforeach;?></div></div></div>
<?php if($c['status']!=='archived'):?><form method="post" class="mt-3" onsubmit="return confirm('Archive this contract?')"><?=csrf_field()?><input type="hidden" name="do" value="archive"><button class="btn btn-sm btn-outline-danger">Archive contract</button></form><?php endif; page_foot();
